insert into eduorbit_prep.prep_subjects (exam_id, name, slug)
select distinct b.exam_id, o.subject_name, o.subject_slug
from official o
join eduorbit_prep.prep_branches b on lower(b.slug) = o.branch_slug or (o.branch_slug = 'cs' and lower(b.slug) = 'cse')
on conflict (exam_id, slug) do nothing;

