insert into eduorbit_prep.prep_branch_subjects (branch_id, subject_id)
select b.id, s.id
from official o
join eduorbit_prep.prep_branches b on lower(b.slug) = o.branch_slug or (o.branch_slug = 'cs' and lower(b.slug) = 'cse')
join eduorbit_prep.prep_subjects s on s.exam_id = b.exam_id and s.slug = o.subject_slug
on conflict (branch_id, subject_id) do nothing;

